// services/authService.js
import * as sodium from 'libsodium-wrappers';
import { AUTH_CONFIG } from '../config/authConfig.js';

export class AuthService {
  static async hashPassword(plainPassword) {
    await sodium.ready;

    const salt = sodium.randombytes_buf(AUTH_CONFIG.ARGON2ID.SALT_LENGTH);
    const hash = sodium.crypto_pwhash(
      AUTH_CONFIG.ARGON2ID.HASH_LENGTH,
      plainPassword,
      salt,
      AUTH_CONFIG.ARGON2ID.TIME_COST,
      AUTH_CONFIG.ARGON2ID.MEMORY_COST,
      AUTH_CONFIG.ARGON2ID.ALGORITHM
    );

    // Return salt + hash (or store separately in DB)
    return {
      hash: sodium.to_hex(hash),
      salt: sodium.to_hex(salt),
      createdAt: new Date().toISOString(),
    };
  }

  static async verifyPassword(plainPassword, storedHash, storedSaltHex) {
    await sodium.ready;

    try {
      const salt = Uint8Array.from(Buffer.from(storedSaltHex, 'hex'));
      const hash = sodium.crypto_pwhash(
        AUTH_CONFIG.ARGON2ID.HASH_LENGTH,
        plainPassword,
        salt,
        AUTH_CONFIG.ARGON2ID.TIME_COST,
        AUTH_CONFIG.ARGON2ID.MEMORY_COST,
        AUTH_CONFIG.ARGON2ID.ALGORITHM
      );

      return sodium.compare(hash, Buffer.from(storedHash, 'hex'));
    } catch {
      return false;
    }
  }
}
```

> ✅ **Security Properties**:
> - Unique salt per user (CSPRNG-generated).
> - No salt reuse.
> - Constant-time comparison via `sodium.compare`.
> - Hashes never exposed in logs.

