### **2. Frontend Session Handler – Pseudocode Implementation**

```javascript
class SessionManager {
  constructor(backendLogoutEndpoint = '/api/logout') {
    this.timeoutMs = 1440 * 60 * 1000; // 24 hours in milliseconds
    this.inactivityTimer = null;
    this.logoutEndpoint = backendLogoutEndpoint;
    this.activityEvents = [
      'click',
      'mousemove',
      'keypress',
      'scroll',
      'touchstart',
      'wheel'
    ];
  }

  start() {
    this.resetTimer();
    this.bindActivityEvents();
    window.addEventListener('beforeunload', () => this.clearEvents());
  }

  resetTimer = () => {
    clearTimeout(this.inactivityTimer);
    this.inactivityTimer = setTimeout(() => {
      this.logout();
    }, this.timeoutMs);
  };

  bindActivityEvents() {
    this.activityEvents.forEach(event => {
      document.addEventListener(event, this.resetTimer, { passive: true });
    });
  }

  clearEvents() {
    this.activityEvents.forEach(event => {
      document.removeEventListener(event, this.resetTimer);
    });
    clearTimeout(this.inactivityTimer);
  }

  async logout() {
    try {
      // Invalidate server-side session
      await fetch(this.logoutEndpoint, { method: 'POST', credentials: 'include' });
    } catch (err) {
      console.warn('Logout request failed, proceeding with local cleanup');
    } finally {
      // Clear frontend state
      this.clearFrontendState();
      window.location.href = '/login';
    }
  }

  clearFrontendState() {
    // Clear in-memory token and app state
    window.__SESSION_TOKEN__ = null;
    sessionStorage.clear();
    // Additional app-specific cleanup (e.g., Redux, context)
  }

  // Optional: Extend session via heartbeat (if needed)
  async extendSession() {
    const res = await fetch('/api/refresh', { method: 'POST', credentials: 'include' });
    if (res.ok) this.resetTimer();
    return res.ok;
  }
}

// Initialize session manager on app load
window.sessionManager = new SessionManager();
window.sessionManager.start();
```

> 🔐 **Security Notes**:
> - Token is **never stored in localStorage/sessionStorage** → mitigates XSS theft.
> - `credentials: 'include'` ensures cookies are sent with cross-origin requests if applicable.
> - `httpOnly` cookies (managed by backend) prevent JS access → defense-in-depth.

